// edge SDK evaluation (deterministic bucketing)
import { createHash } from 'crypto';
function variant(flag, userId){
  const bucket = parseInt(createHash('sha256').update(userId+flag.key).digest('hex').slice(0,8),16) % 100;
  if(bucket >= flag.rollout) return flag.offVariation;
  for(const r of flag.rules) if(r.country===user.country) return r.variation;
  return flag.defaultVariation;
}
// exposure log
kafka.send('exposures', {flag: flag.key, userId, variant: variant(flag, userId), ts: Date.now()})
